import { Component, forwardRef, input } from '@angular/core';
import { FormsModule, NG_VALUE_ACCESSOR } from '@angular/forms';
import { NzInputModule } from 'ng-zorro-antd/input';
import { NzMentionModule } from 'ng-zorro-antd/mention';
import { HrmControl } from '../shared/hrm-control';

/** hrm-mentions — CVA string, textarea gõ @ để nhắc tên. */
@Component({
  selector: 'hrm-mentions',
  imports: [FormsModule, NzInputModule, NzMentionModule],
  template: `
    <nz-mention [nzSuggestions]="suggestions()" [nzPrefix]="prefix()">
      <textarea
        nz-input
        nzMentionTrigger
        [ngModel]="value()"
        (ngModelChange)="emit($event)"
        (blur)="markTouched()"
        [rows]="rows()"
        [placeholder]="placeholder()"
        [disabled]="disabled()"></textarea>
    </nz-mention>
  `,
  host: { class: 'hrm-mentions' },
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => HrmMentions), multi: true }],
})
export class HrmMentions extends HrmControl<string> {
  readonly suggestions = input<string[]>([]);
  readonly prefix = input<string | string[]>('@');
  readonly placeholder = input('');
  readonly rows = input(2);
}
